const inputItems = $input.all();
const output = [];

function cleanLink(link = "") {
  if (!link) return "";

  const value = String(link).trim();

  // Convert markdown links like:
  // [https://site.com](https://site.com)
  // into:
  // https://site.com
  const match = value.match(/\[[^\]]*\]\((https?:\/\/[^)]+)\)/);

  return match ? match[1] : value;
}

function parseResponse(raw) {
  if (typeof raw === "object" && raw !== null) {
    return raw;
  }

  let text = String(raw ?? "").trim();

  text = text
    .replace(/^```json\s*/i, "")
    .replace(/^```\s*/i, "")
    .replace(/\s*```$/, "")
    .replace(/\\_/g, "_")
    .trim();

  let parsed = JSON.parse(text);

  // Handle double-encoded JSON
  if (typeof parsed === "string") {
    parsed = JSON.parse(parsed);
  }

  return parsed;
}

for (const item of inputItems) {
  const raw =
    item.json.output ??
    item.json.text ??
    item.json.response ??
    item.json.content ??
    item.json.message ??
    item.json;

  const data = parseResponse(raw);

  const category = data.category ?? "unknown";

  for (const story of data.stories ?? []) {
    output.push({
      json: {
        category,

        title: story.title ?? "",
        link: cleanLink(story.link),
        published: story.published ?? "",

        priority:
          typeof story.priority === "number"
            ? story.priority
            : null,

        area: story.area ?? "",
        topic: story.topic ?? "",
        type: story.type ?? "",

        summary: story.summary ?? "",

        why_it_matters:
          story.why_it_matters ?? "",

        research_question:
          story.research_question ?? null,

        research_tier:
          story.research_tier ?? null,

        look_for:
          Array.isArray(story.look_for)
            ? story.look_for
            : [],

        best_first_read:
          story.best_first_read === true
      }
    });
  }
}

// Optional: sort highest priority first
output.sort((a, b) => {
  return (b.json.priority ?? 0) - (a.json.priority ?? 0);
});

return output;

const items = $input.all().map(item => item.json);

// =====================================================
// HELPERS
// =====================================================

function escapeHtml(value = "") {
  return String(value)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#039;");
}

function cleanLink(link = "") {
  if (!link) return "";

  const value = String(link).trim();

  const match = value.match(
    /\[[^\]]*\]\((https?:\/\/[^)]+)\)/
  );

  return match ? match[1] : value;
}

function storyCard(item) {
  const link = cleanLink(item.link);

  const metadata = [];

  if (item.priority !== null && item.priority !== undefined) {
    metadata.push(
      `<strong>Priority:</strong> ${escapeHtml(item.priority)}/10`
    );
  }

  if (item.area) {
    metadata.push(
      `<strong>Area:</strong> ${escapeHtml(item.area)}`
    );
  }

  if (item.topic) {
    metadata.push(
      `<strong>Topic:</strong> ${escapeHtml(item.topic)}`
    );
  }

  if (item.type) {
    metadata.push(
      `<strong>Type:</strong> ${escapeHtml(item.type)}`
    );
  }

  if (item.research_tier) {
    metadata.push(
      `<strong>Tier:</strong> ${escapeHtml(item.research_tier)}`
    );
  }

  const lookFor =
    Array.isArray(item.look_for) && item.look_for.length
      ? `
        <div style="margin-top:12px;">
          <strong>🔎 Look for:</strong>
          <ul style="margin-top:6px;">
            ${item.look_for
              .map(q => `<li>${escapeHtml(q)}</li>`)
              .join("")}
          </ul>
        </div>
      `
      : "";

  const researchQuestion =
    item.research_question
      ? `
        <div style="margin-top:10px;">
          <strong>🧪 Research idea:</strong>
          ${escapeHtml(item.research_question)}
        </div>
      `
      : "";

  const whyItMatters =
    item.why_it_matters &&
    item.why_it_matters !== item.summary
      ? `
        <div style="margin-top:10px;">
          <strong>💡 Why it matters:</strong>
          ${escapeHtml(item.why_it_matters)}
        </div>
      `
      : "";

  const bestRead =
    item.best_first_read
      ? `
        <div style="
          font-weight:bold;
          margin-bottom:8px;
        ">
          ⭐ RECOMMENDED FIRST READ
        </div>
      `
      : "";

  return `
    <div style="
      padding:18px 0;
      border-bottom:1px solid #e5e5e5;
    ">

      ${bestRead}

      <div style="
        font-size:18px;
        font-weight:bold;
        line-height:1.35;
      ">
        ${
          link
            ? `
              <a
                href="${escapeHtml(link)}"
                style="
                  color:#111827;
                  text-decoration:none;
                "
              >
                ${escapeHtml(item.title)}
              </a>
            `
            : escapeHtml(item.title)
        }
      </div>

      ${
        item.published
          ? `
            <div style="
              font-size:12px;
              color:#6b7280;
              margin-top:5px;
            ">
              ${escapeHtml(item.published)}
            </div>
          `
          : ""
      }

      ${
        metadata.length
          ? `
            <div style="
              margin-top:7px;
              font-size:13px;
            ">
              ${metadata.join(" &nbsp;•&nbsp; ")}
            </div>
          `
          : ""
      }

      ${
        item.summary
          ? `
            <p style="
              margin:10px 0 0 0;
              line-height:1.55;
            ">
              ${escapeHtml(item.summary)}
            </p>
          `
          : ""
      }

      ${whyItMatters}

      ${lookFor}

      ${researchQuestion}

      ${
        link
          ? `
            <div style="margin-top:12px;">
              <a href="${escapeHtml(link)}">
                Read more →
              </a>
            </div>
          `
          : ""
      }

    </div>
  `;
}

function createSection(title, sectionItems, subtitle = "") {
  if (!sectionItems.length) return "";

  return `
    <div style="margin-top:38px;">

      <h2 style="
        margin:0 0 5px 0;
        font-size:22px;
      ">
        ${title}
      </h2>

      ${
        subtitle
          ? `
            <div style="
              color:#6b7280;
              font-size:14px;
              margin-bottom:8px;
            ">
              ${escapeHtml(subtitle)}
            </div>
          `
          : ""
      }

      ${sectionItems.map(storyCard).join("")}

    </div>
  `;
}

