// =====================================================

const seen = new Set();
const uniqueItems = [];

for (const item of items) {
  const link = cleanLink(item.link);

  const key = link
    ? link.toLowerCase()
    : String(item.title || "").toLowerCase();

  if (!key || seen.has(key)) continue;

  seen.add(key);

  uniqueItems.push({
    ...item,
    link
  });
}

// =====================================================
// SORT
// =====================================================

uniqueItems.sort(
  (a, b) =>
    (b.priority ?? 0) -
    (a.priority ?? 0)
);

