const ai = uniqueItems.filter(
  x => x.category === "ai"
);

const engineering = uniqueItems.filter(
  x => x.category === "engineering"
);

const securityAutomation = uniqueItems.filter(
  x => x.category === "security_automation"
);

const markets = uniqueItems.filter(
  x => x.category === "markets"
);

const research = uniqueItems.filter(
  x => x.category === "research"
);

const researchCore = research.filter(
  x => x.research_tier === "core"
);

const researchStretch = research.filter(
  x => x.research_tier === "stretch"
);

const researchWatch = research.filter(
  x => x.research_tier === "watchlist"
);

