// =====================================================

const newsItems = uniqueItems.filter(
  x => x.category !== "research"
);

const bigThree = [...newsItems]
  .sort(
    (a, b) =>
      (b.priority ?? 0) -
      (a.priority ?? 0)
  )
  .slice(0, 3);

// =====================================================
// COUNTS
// =====================================================

const newsCount = newsItems.length;
const researchCount = research.length;

// =====================================================
// DATE
// =====================================================

const today = new Date().toLocaleDateString(
  "en-US",
  {
    weekday: "long",
    month: "long",
    day: "numeric",
    year: "numeric"
  }
);

// =====================================================
// BIG 3 HTML
// =====================================================

const bigThreeHtml = bigThree.length
  ? `
    <div style="
      margin-top:28px;
      padding:20px;
      border:1px solid #d1d5db;
      border-radius:10px;
      background:#f9fafb;
    ">

      <h2 style="margin-top:0;">
        🚨 The Big 3
      </h2>

      <p>
        If you only have five minutes this morning,
        start here.
      </p>

      ${bigThree.map(storyCard).join("")}

    </div>
  `
  : "";

// =====================================================
// HTML
// =====================================================

const html = `
<!DOCTYPE html>
<html>

<body style="
  margin:0;
  padding:0;
  background:#ffffff;
  color:#111827;
  font-family:Arial, Helvetica, sans-serif;
">

<div style="
