    font-size:14px;
    color:#6b7280;
    margin-bottom:22px;
  ">
    ${today}
  </div>

  <p style="
    font-size:17px;
    line-height:1.6;
  ">
    Morning 👋 Your agents scanned the noise and pulled
    <strong>${newsCount} tech/news signals</strong>
    and
    <strong>${researchCount} research papers</strong>
    worth keeping on your radar today.
  </p>

  ${bigThreeHtml}

  ${createSection(
    "🤖 AI Radar",
    ai,
    "Models, agents, reasoning, memory, tooling and frontier AI."
  )}

  ${createSection(
    "💻 Builder Desk",
    engineering,
    "AI coding, developer tools, cloud infrastructure and engineering."
  )}

  ${createSection(
