  let text = String(raw ?? "").trim();

  // Remove Markdown fences
  text = text
    .replace(/^```json\s*/i, "")
    .replace(/^```\s*/i, "")
    .replace(/\s*```$/, "")
    .replace(/\\_/g, "_")
    .trim();

  let parsed;

  try {
    parsed = JSON.parse(text);

    // Handle JSON encoded inside a JSON string
    if (typeof parsed === "string") {
      parsed = JSON.parse(parsed);
    }
  } catch (error) {
    throw new Error(
      `Could not parse agent response.\n\n${error.message}\n\nRaw:\n${text}`
    );
  }

  return parsed;
}

function pushStory(story, category, extra = {}) {
  if (!story || !story.title) return;

  output.push({
    json: {
      content_type: "news",

      category,

      title: story.title ?? "",
      link: cleanLink(story.link),

      published: story.published ?? "",

      priority:
        typeof story.priority === "number"
          ? story.priority
          : null,

      area: story.area ?? "",
      topic: story.topic ?? "",
      type: story.type ?? "",

      summary:
        story.summary ??
        story.why_read ??
        story.reason ??
        "",

      why_it_matters:
        story.why_it_matters ??
        story.why_read ??
        story.reason ??
        "",

      research_question:
        story.research_question ?? null,

      look_for:
        Array.isArray(story.look_for)
          ? story.look_for
          : [],

      best_first_read:
        story.best_first_read === true,

      ...extra
    }
  });
}

// -----------------------------------
// Process every input item
// -----------------------------------

for (const item of inputItems) {

  const raw =
    item.json.output ??
    item.json.text ??
    item.json.response ??
    item.json.content ??
    item.json.message ??
    item.json;

  const data = parseAgentResponse(raw);

  // -----------------------------------
  // Standard news-agent format
  // -----------------------------------

  if (Array.isArray(data.stories)) {

    const category = data.category ?? "unknown";

    for (const story of data.stories) {
      pushStory(story, category);
    }

    continue;
  }

  // -----------------------------------
  // Research-agent format
  // -----------------------------------

  const bestTitle =
    data.best_first_read?.title ??
    null;

  for (const paper of data.core_reads ?? []) {

    pushStory(
      paper,
      "research",
      {
        content_type: "research",
        research_tier: "core",
        best_first_read:
          paper.title === bestTitle
      }
    );

  }

  for (const paper of data.stretch_reads ?? []) {

    pushStory(
      paper,
      "research",
      {
        content_type: "research",
        research_tier: "stretch",
        best_first_read:
          paper.title === bestTitle
      }
    );

  }

  for (const paper of data.watchlist ?? []) {

    pushStory(
      paper,
      "research",
      {
        content_type: "research",
        research_tier: "watchlist",
        best_first_read:
          paper.title === bestTitle
      }
    );

  }
}

// Highest priority first
output.sort((a, b) => {
  return (b.json.priority ?? 0) - (a.json.priority ?? 0);
});

return output;
